namespace Accyourate.App.AssetManagement.Services;
public sealed class SupplierRmaCapaGovernanceReview{public int Id{get;init;}public string Outcome{get;init;}="";public string EvaluationStatus{get;init;}="";public int TotalActions{get;init;}public int OverdueActions{get;init;}public double OnTimePercentage{get;init;}public double AverageCompletionDays{get;init;}public string Notes{get;init;}="";public string Decisions{get;init;}="";public string Reviewer{get;init;}="";public string ReviewDate{get;init;}="";public string NextReviewDate{get;init;}="";public string ReportPath{get;init;}="";public bool ReportAvailable=>File.Exists(ReportPath);public bool IsOverdue=>DateTime.TryParse(NextReviewDate,out var d)&&d.Date<DateTime.Today;public bool IsDueSoon=>DateTime.TryParse(NextReviewDate,out var d)&&d.Date>=DateTime.Today&&d.Date<=DateTime.Today.AddDays(30);}
public sealed class SupplierRmaCapaGovernanceReviewService
{
 private readonly string _cs;private readonly SettingsService _settings=new();public SupplierRmaCapaGovernanceReviewService(string? db=null){var folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"AccyourateEnterpriseX");Directory.CreateDirectory(folder);_cs=$"Data Source={db??Path.Combine(folder,"accyourate-assets.db")}";using var c=Open();using var q=c.CreateCommand();q.CommandText="CREATE TABLE IF NOT EXISTS SupplierRmaCapaGovernanceReviews(Id INTEGER PRIMARY KEY AUTOINCREMENT,Outcome TEXT NOT NULL,EvaluationStatus TEXT NOT NULL,TotalActions INTEGER NOT NULL,OverdueActions INTEGER NOT NULL,OnTimePercentage REAL NOT NULL,AverageCompletionDays REAL NOT NULL,Notes TEXT NOT NULL,Decisions TEXT NOT NULL,Reviewer TEXT NOT NULL,ReviewDate TEXT NOT NULL,NextReviewDate TEXT NOT NULL,ReportPath TEXT NOT NULL);CREATE TABLE IF NOT EXISTS SupplierRmaCapaGovernanceReviewNotifications(NotificationKey TEXT PRIMARY KEY,ReviewId INTEGER NOT NULL,CreatedAt TEXT NOT NULL);";q.ExecuteNonQuery();}
 public IReadOnlyList<SupplierRmaCapaGovernanceReview> GetAll(){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT Id,Outcome,EvaluationStatus,TotalActions,OverdueActions,OnTimePercentage,AverageCompletionDays,Notes,Decisions,Reviewer,ReviewDate,NextReviewDate,ReportPath FROM SupplierRmaCapaGovernanceReviews ORDER BY Id DESC;";using var r=q.ExecuteReader();var v=new List<SupplierRmaCapaGovernanceReview>();while(r.Read())v.Add(new(){Id=r.GetInt32(0),Outcome=r.GetString(1),EvaluationStatus=r.GetString(2),TotalActions=r.GetInt32(3),OverdueActions=r.GetInt32(4),OnTimePercentage=r.GetDouble(5),AverageCompletionDays=r.GetDouble(6),Notes=r.GetString(7),Decisions=r.GetString(8),Reviewer=r.GetString(9),ReviewDate=r.GetString(10),NextReviewDate=r.GetString(11),ReportPath=r.GetString(12)});return v;}
 public SupplierRmaCapaGovernanceReview Create(string outcome,string notes,string decisions,string reviewer,string nextReview,SupplierRmaCapaGovernanceActionAnalytics analytics,SupplierRmaCapaGovernanceGoalEvaluation evaluation){if(outcome is not("Confermato" or "Con riserva" or "Non conforme"))throw new InvalidOperationException("Esito non valido.");if(string.IsNullOrWhiteSpace(notes)||string.IsNullOrWhiteSpace(decisions)||string.IsNullOrWhiteSpace(reviewer)||!DateTime.TryParse(nextReview,out var next))throw new InvalidOperationException("Note, decisioni, responsabile e prossimo riesame sono obbligatori.");using var c=Open();using var q=c.CreateCommand();q.CommandText="INSERT INTO SupplierRmaCapaGovernanceReviews(Outcome,EvaluationStatus,TotalActions,OverdueActions,OnTimePercentage,AverageCompletionDays,Notes,Decisions,Reviewer,ReviewDate,NextReviewDate,ReportPath) VALUES($o,$e,$t,$s,$p,$m,$n,$d,$r,$at,$next,'');SELECT last_insert_rowid();";q.Parameters.AddWithValue("$o",outcome);q.Parameters.AddWithValue("$e",evaluation.OverallStatus);q.Parameters.AddWithValue("$t",analytics.Total);q.Parameters.AddWithValue("$s",analytics.Overdue);q.Parameters.AddWithValue("$p",analytics.OnTimePercentage);q.Parameters.AddWithValue("$m",analytics.AverageCompletionDays);q.Parameters.AddWithValue("$n",notes.Trim());q.Parameters.AddWithValue("$d",decisions.Trim());q.Parameters.AddWithValue("$r",reviewer.Trim());q.Parameters.AddWithValue("$at",DateTime.Now.ToString("s"));q.Parameters.AddWithValue("$next",next.ToString("yyyy-MM-dd"));var id=Convert.ToInt32(q.ExecuteScalar());var item=new SupplierRmaCapaGovernanceReview{Id=id,Outcome=outcome,EvaluationStatus=evaluation.OverallStatus,TotalActions=analytics.Total,OverdueActions=analytics.Overdue,OnTimePercentage=analytics.OnTimePercentage,AverageCompletionDays=analytics.AverageCompletionDays,Notes=notes.Trim(),Decisions=decisions.Trim(),Reviewer=reviewer.Trim(),ReviewDate=DateTime.Now.ToString("s"),NextReviewDate=next.ToString("yyyy-MM-dd")};var report=GeneratePdf(item);using var update=c.CreateCommand();update.CommandText="UPDATE SupplierRmaCapaGovernanceReviews SET ReportPath=$p WHERE Id=$id;";update.Parameters.AddWithValue("$p",report);update.Parameters.AddWithValue("$id",id);update.ExecuteNonQuery();return new(){Id=item.Id,Outcome=item.Outcome,EvaluationStatus=item.EvaluationStatus,TotalActions=item.TotalActions,OverdueActions=item.OverdueActions,OnTimePercentage=item.OnTimePercentage,AverageCompletionDays=item.AverageCompletionDays,Notes=item.Notes,Decisions=item.Decisions,Reviewer=item.Reviewer,ReviewDate=item.ReviewDate,NextReviewDate=item.NextReviewDate,ReportPath=report};}
 public int PublishAlerts(NotificationService? n=null){n??=new NotificationService();var count=0;foreach(var x in GetAll().Where(x=>x.IsOverdue||x.IsDueSoon)){var key=$"capa-governance-review:{x.Id}:{(x.IsOverdue?"overdue":"due")}:{DateTime.Today:yyyyMMdd}";using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM SupplierRmaCapaGovernanceReviewNotifications WHERE NotificationKey=$k;";q.Parameters.AddWithValue("$k",key);if(Convert.ToInt32(q.ExecuteScalar())>0)continue;n.Publish(x.IsOverdue?"Riesame Governance CAPA scaduto":"Riesame Governance CAPA in scadenza",$"Prossimo riesame previsto il {Date(x.NextReviewDate)}.",NotificationCategory.Asset,x.IsOverdue?NotificationPriority.Critical:NotificationPriority.High,"Riesame Governance CAPA","open-rma-corrective-actions",x.Id.ToString());using var a=c.CreateCommand();a.CommandText="INSERT INTO SupplierRmaCapaGovernanceReviewNotifications(NotificationKey,ReviewId,CreatedAt) VALUES($k,$id,$d);";a.Parameters.AddWithValue("$k",key);a.Parameters.AddWithValue("$id",x.Id);a.Parameters.AddWithValue("$d",DateTime.Now.ToString("s"));a.ExecuteNonQuery();count++;}return count;}
 private string GeneratePdf(SupplierRmaCapaGovernanceReview x){var s=_settings.Load();var t=s.DocumentTemplate??new DocumentTemplateSettings();var d=new SimplePdfDocument{Title="Verbale riesame Governance CAPA"};Brand(d,s,t,$"CAPA-REV-{x.Id:D6}");d.AddTitle("Verbale riesame periodico Governance CAPA");d.AddKeyValue("Numero riesame",x.Id.ToString("D6"));d.AddKeyValue("Data",Date(x.ReviewDate));d.AddKeyValue("Responsabile",x.Reviewer);d.AddKeyValue("Prossimo riesame",Date(x.NextReviewDate));d.AddStatus("Esito del riesame",x.Outcome);d.AddStatus("Valutazione indicatori",x.EvaluationStatus);d.AddHeading("Indicatori consolidati");d.AddKeyValue("Azioni totali",x.TotalActions.ToString());d.AddKeyValue("Azioni scadute",x.OverdueActions.ToString());d.AddKeyValue("Completate entro scadenza",$"{x.OnTimePercentage:N1}%");d.AddKeyValue("Tempo medio completamento",$"{x.AverageCompletionDays:N1} giorni");d.AddHeading("Osservazioni");d.AddText(x.Notes);d.AddHeading("Decisioni e azioni conseguenti");d.AddText(x.Decisions);d.AddSignaturePair("Responsabile qualita","Direzione");var folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"Accyourate Enterprise X","Riesami Governance CAPA");return new PdfExportService().Export(d,folder,$"Riesame-Governance-CAPA-{x.Id:D6}-{DateTime.Now:yyyyMMdd-HHmmss}");}
 private static string Date(string v)=>DateTime.TryParse(v,out var d)?d.ToString("dd/MM/yyyy HH:mm"):v;private static void Brand(SimplePdfDocument d,ApplicationSettings s,DocumentTemplateSettings t,string code){d.Branding.CompanyName=string.IsNullOrWhiteSpace(s.Company.LegalName)?s.Company.CompanyName:s.Company.LegalName;d.Branding.CompanyDetailLines.AddRange(new[]{s.Company.Address,string.Join(" ",new[]{s.Company.City,s.Company.Province}.Where(v=>!string.IsNullOrWhiteSpace(v))),string.Join(" - ",new[]{s.Company.Phone,s.Company.Email}.Where(v=>!string.IsNullOrWhiteSpace(v)))}.Where(v=>!string.IsNullOrWhiteSpace(v)));d.Branding.HeaderLayout=t.HeaderLayout;d.Branding.LogoPath=s.Company.LogoPath;d.Branding.LogoSize=t.LogoSize;d.Branding.LogoPosition=t.LogoPosition;d.Branding.PrimaryColor=t.PrimaryColor;d.Branding.DocumentLabel="RIESAME GOVERNANCE CAPA";d.Branding.DocumentCode=code;d.Branding.DocumentVersion=t.DocumentVersion;d.Branding.FooterText=t.FooterText;d.Branding.ConfidentialityText=t.ConfidentialityText;d.Branding.ShowLogo=t.ShowLogo;d.Branding.ShowCompanyDetails=t.ShowCompanyDetails;d.Branding.ShowDocumentMetadata=t.ShowDocumentMetadata;d.Branding.ShowFooter=t.ShowFooter;d.Branding.ShowPageNumber=t.ShowPageNumber;d.Branding.ShowPrintTimestamp=t.ShowPrintTimestamp;}private SqliteConnection Open(){var c=new SqliteConnection(_cs);c.Open();return c;}
